import { schnorr } from '@noble/curves/secp256k1.js';
import { bytesToHex, hexToBytes } from '@noble/hashes/utils.js';
import { describe, expect, it } from 'vitest';
import { sha256Hex } from './canonical.js';
import { schnorrPublicKeyHex, schnorrSign, schnorrVerifier } from './crypto.js';

// BIP-340 official vectors, downloaded at every run (not kept in the repo: the BIP text is
// BSD-2-Clause, which asks for a copyright notice, while its code is BSD-2-Clause OR MIT OR
// CC0-1.0, and the CSV is generated by that code). Pinned to the last commit that changed the
// file; BIP-340 publishes no checksum, so the sha256 is pinned here, computed on 22/10/2026.
// Without network the suite is skipped with a warning; an HTTP error or a wrong checksum fails.
const BIP340_VECTORS_URL =
  'https://raw.githubusercontent.com/bitcoin/bips/200f9b26fe0a2f235a2af8b30c4be9f12f6bc9cb/bip-0340/test-vectors.csv';
const BIP340_VECTORS_SHA256 = '34c9d1d9c3a88d524bc80778540dc43f8306ec249a7485293063c376db851c2d';

async function loadVectors(): Promise<string | null> {
  let res: Response;
  try {
    res = await fetch(BIP340_VECTORS_URL, { signal: AbortSignal.timeout(20_000) });
  } catch (e) {
    const reason = e instanceof Error ? e.message : String(e);
    process.stderr.write(`\nWARNING: BIP-340 vector tests skipped, no network (${reason})\n`);
    return null;
  }
  if (!res.ok) throw new Error(`cannot download ${BIP340_VECTORS_URL}: HTTP ${res.status}`);
  const raw = await res.text();
  // Nothing below runs on vectors that are not the pinned file.
  if (sha256Hex(raw) !== BIP340_VECTORS_SHA256)
    throw new Error(`${BIP340_VECTORS_URL} does not match the pinned sha256`);
  return raw;
}

const raw = await loadVectors();

describe('schnorrVerifier on the BIP-340 vectors (needs network)', () => {
  if (raw === null) {
    it.skip('no network: vectors not downloaded, suite skipped', () => {});
    return;
  }
  // Columns: index, secret key, public key, aux_rand, message, signature, result, comment.
  const bip340 = raw
    .trim()
    .split('\n')
    .slice(1)
    .map((line) => {
      const [index, secret, pub, aux, msg, sig, ok, comment] = line.split(',');
      return {
        index: Number(index),
        secret: (secret ?? '').toLowerCase(),
        pub: (pub ?? '').toLowerCase(),
        aux: (aux ?? '').toLowerCase(),
        msg: (msg ?? '').toLowerCase(),
        sig: (sig ?? '').toLowerCase(),
        ok: ok === 'TRUE',
        comment: comment ?? '',
      };
    });
  const digestVectors = bip340.filter((v) => v.msg.length === 64);

  it('uses the pinned file', () => {
    expect(sha256Hex(raw)).toBe(BIP340_VECTORS_SHA256);
  });

  it.each(digestVectors)('vector $index: $ok $comment', (v) => {
    expect(schnorrVerifier.verify(v.pub, v.msg, v.sig)).toBe(v.ok);
  });

  it.each(digestVectors.filter((v) => v.secret !== ''))(
    'vector $index: key and signature from the secret',
    (v) => {
      expect(schnorrPublicKeyHex(v.secret)).toBe(v.pub);
      // The vectors fix aux_rand; schnorrSign draws it, so check the result verifies instead.
      expect(
        bytesToHex(schnorr.sign(hexToBytes(v.msg), hexToBytes(v.secret), hexToBytes(v.aux))),
      ).toBe(v.sig);
      expect(schnorrVerifier.verify(v.pub, v.msg, schnorrSign(v.secret, v.msg))).toBe(true);
    },
  );

  it('refuses messages that are not 32-byte digests (vectors 15-18 sign other lengths)', () => {
    const others = bip340.filter((v) => v.msg.length !== 64);
    expect(others.map((v) => v.index)).toEqual([15, 16, 17, 18]);
    for (const v of others) expect(schnorrVerifier.verify(v.pub, v.msg, v.sig)).toBe(false);
  });
});
